nix
{ pkgs }:
let
  zigVersion = "0.14.1";
  zigUrl = "https://ziglang.org/download/0.14.1/zig-x86_64-linux-0.14.1.tar.xz";
  futharkVersion = "0.26.4";
  futharkUrl = "https://github.com/diku-dk/futhark/releases/download/v0.26.4/futhark-0.26.4-linux-x86_64.tar.xz";
in {
  deps = [
    pkgs.python311
    pkgs.python311Packages.pip
    pkgs.python311Packages.setuptools
    pkgs.python311Packages.wheel
    pkgs.git
    pkgs.curl
    pkgs.jq
    pkgs.cacert
    pkgs.openssl
    pkgs.gcc
    pkgs.xz
    pkgs.gnutar
  ];

  env = {
    PYTHONBIN = "${pkgs.python311}/bin/python3.11";
    LANG = "en_US.UTF-8";
    SSL_CERT_FILE = "${pkgs.cacert}/etc/ssl/certs/ca-bundle.crt";
    NIX_SSL_CERT_FILE = "${pkgs.cacert}/etc/ssl/certs/ca-bundle.crt";
    ZIG_VERSION = zigVersion;
    ZIG_URL = zigUrl;
    FUTHARK_VERSION = futharkVersion;
    FUTHARK_URL = futharkUrl;
  };

  packages = [
    (pkgs.stdenv.mkDerivation {
      pname = "zig-bin";
      version = zigVersion;
      src = pkgs.fetchurl {
        url = zigUrl;
        sha256 = "";
      };
      nativeBuildInputs = [ pkgs.xz pkgs.gnutar ];
      dontConfigure = true;
      dontBuild = true;
      sourceRoot = ".";
      unpackPhase = ''
        tar -xJf "$src"
      '';
      installPhase = ''
        mkdir -p "$out"
        cp -R zig-x86_64-linux-${zigVersion}/* "$out"/
      '';
    })

    (pkgs.stdenv.mkDerivation {
      pname = "futhark-bin";
      version = futharkVersion;
      src = pkgs.fetchurl {
        url = futharkUrl;
        sha256 = "";
      };
      nativeBuildInputs = [ pkgs.xz pkgs.gnutar ];
      dontConfigure = true;
      dontBuild = true;
      sourceRoot = ".";
      unpackPhase = ''
        tar -xJf "$src"
      '';
      installPhase = ''
        mkdir -p "$out"
        cp -R futhark-0.26.4-linux-x86_64/* "$out"/
      '';
    })
  ];
}

